--
-- Name: fill_attendance_names(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_attendance_names() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.student_name IS NULL OR btrim(NEW.student_name) = '' THEN
        SELECT name INTO NEW.student_name FROM people WHERE LOWER(roll_num) = LOWER(NEW.student_roll);
    END IF;
    IF NEW.marked_by_name IS NULL OR btrim(NEW.marked_by_name) = '' THEN
        SELECT name INTO NEW.marked_by_name FROM people WHERE LOWER(roll_num) = LOWER(NEW.marked_by_roll);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: fill_enrollment_student_name(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_enrollment_student_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.student_name IS NULL OR btrim(NEW.student_name) = '' THEN
        SELECT name INTO NEW.student_name FROM people WHERE LOWER(roll_num) = LOWER(NEW.student_roll);
    END IF;
    RETURN NEW;
END;
$$;


